  "lectureBuilder.stringLiteral163": "कहानी",
  "lectureBuilder.stringLiteral164": "एकल सुधार पूर्ववत का समर्थन नहीं करते हैं।",
  "lectureBuilder.stringLiteral165": "(खाली)",
  "lectureBuilder.stringLiteral166": "(खाली)",
  "lectureBuilder.stringLiteral167": "स्लाइड हटा दी गई है।",
  "lectureBuilder.stringLiteral168": " (पाठ निकालना पूर्ण)",
  "lectureBuilder.stringLiteral169": "अपलोड विफल",
  "lectureBuilder.jsxText170": "स्लाइड अपलोड करें",
  "lectureBuilder.jsxText171": "PPT, PDF, या छवि फ़ाइलें अपलोड करें। PPT/PDF स्वचालित रूप से अलग-अलग स्लाइड छवियों में परिवर्तित हो जाएंगे।",
  "lectureBuilder.stringLiteral172": "परिवर्तित हो रहा है...",
  "lectureBuilder.stringLiteral173": "फ़ाइल अपलोड",
  "lectureBuilder.jsxText174": "PPT/PDF को स्लाइड छवियों में परिवर्तित किया जा रहा है। फ़ाइल आकार के आधार पर इसमें कुछ समय लग सकता है।",
  "lectureBuilder.jsxText175": "फ़ाइल अपलोड करने के लिए खींचें या क्लिक करें",
  "lectureBuilder.jsxText176": "PPT (.pptx), PDF, छवि (.png, .jpg) का समर्थन करता है",
  "lectureBuilder.jsxText177": "PPT/PDF फ़ाइलें सर्वर पर स्वचालित रूप से प्रति-स्लाइड छवियों में परिवर्तित हो जाती हैं।",
  "lectureBuilder.jsxText178": "PPT/PDF पाठ निकालना पूर्ण (",
  "lectureBuilder.jsxText179": " स्लाइड)",
  "lectureBuilder.jsxText180": "आप निकाले गए पाठ को स्वचालित रूप से स्क्रिप्ट ड्राफ्ट के रूप में लागू कर सकते हैं। इसे चरण 2 में संपादित किया जा सकता है।",
  "lectureBuilder.stringLiteral181": "स्क्रिप्ट लागू करने में विफल",
  "lectureBuilder.jsxText182": "स्क्रिप्ट ड्राफ्ट लागू करें",
  "lectureBuilder.stringLiteral183": "(कोई पाठ नहीं)",
  "lectureBuilder.jsxText184": "... और",
  "lectureBuilder.jsxText185": " और स्लाइड",
  "lectureBuilder.stringLiteral186": "दुभाषिया सेटिंग्स सहेजी गईं।",
  "lectureBuilder.stringLiteral187": "कोरियाई",
  "lectureBuilder.stringLiteral188": "अवतार सेटिंग्स सहेजी गईं।",
  "lectureBuilder.stringLiteral189": "एम्बेडेड सामग्री सहेजी गई।",
  "lectureBuilder.stringLiteral190": "एम्बेडेड सामग्री हटा दी गई।",
  "lectureBuilder.stringLiteral191": "संक्रमण प्रभाव सहेजा गया।",
  "lectureBuilder.stringLiteral192": "AI व्हाइटबोर्ड सामग्री निर्माण पूर्ण।",
  "lectureBuilder.stringLiteral193": "एनोटेशन हटा दिया गया है।",
  "lectureBuilder.stringLiteral194": "एनोटेशन हटा दिया गया है।",
  "lectureBuilder.stringLiteral195": "सभी पेन ड्रॉइंग हटा दिए गए हैं।",
  "lectureBuilder.jsxText196": "मिलान संपादक",
  "lectureBuilder.jsxText197": "प्रत्येक स्लाइड पर स्क्रिप्ट रखें और पेन से सीधे कैनवास पर ड्रा करें।",
  "lectureBuilder.stringLiteral198": "वर्तमान स्लाइड",
