  "lectureBuilder.jsxText213": "स्लाइड",
  "lectureBuilder.jsxText214": "अवतार सेटिंग्स",
  "lectureBuilder.jsxText215": "इस स्लाइड में अवतार का आकार और स्थान समायोजित करें।",
