  "lectureBuilder.stringLiteral306": "कृपया 20एमबी से कम की पृष्ठभूमि संगीत फ़ाइलें अपलोड करें।",
  "lectureBuilder.stringLiteral307": "बैकग्राउंड म्यूजिक अपलोड कर दिया गया है",
